#!/bin/bash
fail=0
tab=$'\t'
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
# the header line and the other rooms' bookings are kept as they were
[ "$(head -1 "$t")" = "# room${tab}date${tab}start${tab}end${tab}who" ] || { echo "header changed"; fail=1; }
[ "$(grep -c .  "$t")" = 2 ] || { echo "other bookings changed"; fail=1; }
grep -q "^kaede${tab}2026-01-05${tab}13:00${tab}14:00${tab}y$" "$t" || { echo "kaede booking removed"; fail=1; }
# not found: exit 1, message on stderr only
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
[ "$rc" = 1 ] || { echo "not found should exit 1, got $rc"; fail=1; }
[ -z "$out" ] || { echo "not found should print nothing on stdout: $out"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null | grep -q '^not found: aoi 2026-01-05 11:00$' || { echo "not found message not on stderr"; fail=1; }
rm -f "$t"

# same date and start in another room: that booking must stay
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$t"
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel aoi failed"; fail=1; }
grep -q "^kaede${tab}2026-01-05${tab}09:00${tab}10:00${tab}y$" "$t" || { echo "kaede removed by cancel of aoi"; fail=1; }
rm -f "$t"

# wrong number of arguments: exit 2, usage on stderr only
out=$(bash src/cancel.sh aoi 2>/dev/null); rc=$?
[ "$rc" = 2 ] || { echo "usage should exit 2, got $rc"; fail=1; }
[ -z "$out" ] || { echo "usage should print nothing on stdout: $out"; fail=1; }
bash src/cancel.sh aoi 2>&1 >/dev/null | grep -q '^usage: cancel.sh ROOM DATE START$' || { echo "usage message not on stderr"; fail=1; }
exit $fail

